package com.timetune.service;
import com.timetune.domain.GameSession;import com.timetune.domain.Song;import org.springframework.stereotype.Service;import java.util.List;import java.util.UUID;
@Service public class GameSessionService {private final GameEngineService engine;public GameSessionService(GameEngineService e){engine=e;}public GameSession createLocalGame(List<String> names){return engine.create(names,GameSession.Mode.LOCAL);}public GameSession get(String id){return engine.require(UUID.fromString(id));}public Song drawNextSong(GameSession s){return engine.prompt(s.getId());}}